"""Dependency-free interactive HTML presentation for the dashboard view models."""

import json


_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Disaster Information Intelligence | Operations</title>
<style>
:root{--bg:#0b1220;--panel:#111c2d;--line:#24344c;--text:#e7eef9;--muted:#9aacc3;--accent:#48b6a8;--red:#ef6a6a;--amber:#f1b85b;--blue:#70a8ff;--green:#68c78e}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 Segoe UI,Arial,sans-serif}header{padding:20px 26px 12px;border-bottom:1px solid var(--line);position:sticky;top:0;background:#0b1220f2;z-index:3}h1{font-size:22px;margin:0 0 4px}h2{font-size:18px;margin:0 0 14px}h3{font-size:15px;margin:14px 0 7px}.muted{color:var(--muted)}.banner{padding:8px 12px;border-radius:6px;background:#493b1c;color:#ffe3a2;display:inline-block;font-weight:700;margin:8px 0}.nav{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.nav button,.button{background:#15243a;border:1px solid var(--line);color:var(--text);padding:8px 12px;border-radius:6px;cursor:pointer}.nav button.active,.nav button:hover{background:#174b50;border-color:var(--accent)}main{padding:20px 26px;max-width:1600px;margin:auto}.page{display:none}.page.active{display:block}.grid{display:grid;gap:12px}.kpis{grid-template-columns:repeat(auto-fit,minmax(155px,1fr))}.two{grid-template-columns:repeat(auto-fit,minmax(320px,1fr))}.card{background:var(--panel);border:1px solid var(--line);border-radius:9px;padding:14px;min-width:0}.kpi{font-size:26px;font-weight:700;margin-top:4px}.label{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em}.notice{border-left:3px solid var(--amber);padding:10px 12px;background:#292519;margin:10px 0}.good{color:var(--green)}.bad{color:var(--red)}.warn{color:var(--amber)}.filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}.filters label{display:grid;gap:3px;color:var(--muted);font-size:12px}select,input{min-width:125px;background:#0b1423;border:1px solid var(--line);border-radius:5px;color:var(--text);padding:7px}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;vertical-align:top;padding:8px;border-bottom:1px solid var(--line)}th{color:#b7c7dc;position:sticky;top:0;background:#111c2d}tr.selectable{cursor:pointer}tr.selectable:hover{background:#1a2a40}.scroll{overflow:auto;max-height:540px}.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:2px 8px;margin:2px;font-size:11px}.level-CRITICAL{color:#ff9999;border-color:#bd5050}.level-HIGH{color:#ffc273;border-color:#a87332}.level-MEDIUM{color:#90c0ff;border-color:#5279ae}.level-LOW,.level-INFO{color:#b6c5d7}.barrow{display:grid;grid-template-columns:115px 1fr 35px;gap:8px;align-items:center;margin:7px 0}.bar{height:10px;background:#0a1321;border-radius:8px;overflow:hidden}.bar>i{display:block;height:100%;background:var(--accent)}.detail section{padding:8px 0;border-top:1px solid var(--line)}.detail pre{white-space:pre-wrap;word-break:break-word;font:13px/1.5 inherit;margin:4px 0}.mapbox{width:100%;background:#0a1524;border:1px solid var(--line);border-radius:7px}.mapbox svg{display:block;width:100%;height:auto}.mapgrid{stroke:#24344c;stroke-width:1}.point{cursor:pointer;stroke:#08101c;stroke-width:2}.legend{display:flex;gap:12px;flex-wrap:wrap;font-size:12px;color:var(--muted)}.empty{padding:18px;color:var(--muted);text-align:center}.health{display:grid;grid-template-columns:110px 120px 1fr;gap:10px;padding:8px;border-bottom:1px solid var(--line)}.footer{margin-top:30px;padding:16px;border-top:1px solid var(--line);color:var(--muted);font-size:12px}@media(max-width:650px){header,main{padding:14px}.health{grid-template-columns:75px 95px 1fr}table{font-size:12px}th,td{padding:6px}}
</style></head><body>
<header><h1>Disaster Information Intelligence</h1><div id="mode" class="banner"></div><div class="muted">Operational decision support • source-of-truth scores and alert decisions are consumed from Phases 5–9</div><nav class="nav" id="nav"></nav></header>
<main>
<section id="overview" class="page active"><h2>Situation overview</h2><div id="kpis" class="grid kpis"></div><div class="notice">Priority is the existing Phase 5 operational ranking. Confidence is evidence quality, not a calibrated probability. This dashboard does not predict disasters or dispatch responders.</div><div class="grid two"><div class="card"><h3>Priority distribution</h3><div id="priority-chart"></div></div><div class="card"><h3>Severity, urgency and confidence</h3><div id="score-charts"></div></div><div class="card"><h3>Alert levels</h3><div id="alert-chart"></div></div><div class="card"><h3>Highest Phase 5 priorities</h3><div id="ranked"></div></div></div></section>
<section id="incidents" class="page"><h2>Incident register</h2><div class="filters" id="incident-filters"></div><div class="card scroll"><div id="incident-table"></div></div><div class="card detail" id="incident-detail"><div class="empty">Select an incident row to inspect source evidence and upstream intelligence.</div></div></section>
<section id="alerts" class="page"><h2>Alerts and suppression</h2><div class="filters" id="alert-filters"></div><div class="notice">Phase 9 is the source of alert decisions. Mock notification status does not mean an external authority was reached.</div><div class="card scroll" id="alert-table"></div><div class="card detail" id="alert-detail"><div class="empty">Select an alert to inspect rules, escalation, suppression and notification status.</div></div><div class="card"><h3>Available alert history</h3><p class="muted">Alert history is limited to the currently available in-memory operational state represented in the loaded records. No missing timeline events are inferred.</p></div></section>
<section id="spatial" class="page"><h2>Spatial view</h2><div class="notice">Mentioned location ≠ geocoded location ≠ verified coordinates. Only upstream Phase 6 success-status, range-valid points appear here. Synthetic coordinates are labeled.</div><div id="map-filters" class="filters"></div><div class="card"><div class="legend"><span>Red: critical alert</span><span>Amber: high alert/priority</span><span>Blue: other valid point</span><span>Outlined ring: hotspot</span></div><div id="map" class="mapbox"></div><div id="map-detail" class="detail"></div></div><div class="grid two"><div class="card"><h3>Spatial summary</h3><div id="spatial-kpis"></div></div><div class="card"><h3>Unresolved locations</h3><div id="unresolved"></div></div></div></section>
<section id="monitoring" class="page"><h2>Monitoring and ingestion</h2><div class="notice">Events describe ingestion state; incidents describe downstream intelligence. This view consumes Phase 8 records and does not re-run identity or monitoring logic.</div><div id="monitoring-kpis" class="grid kpis"></div><div class="card"><h3>Event stream</h3><div class="scroll" id="monitoring-table"></div></div><div class="card"><h3>Pipeline processing statuses</h3><div id="phase-statuses"></div></div></section>
<section id="intelligence" class="page"><h2>Grounded generative intelligence</h2><div class="notice">Generated narrative is grounded in structured system evidence but is not guaranteed to be hallucination-free. Recommendations are decision support for human review, not autonomous commands.</div><div class="filters"><label>Incident<select id="intelligence-select"></select></label></div><div id="intelligence-detail" class="card detail"></div></section>
<section id="health" class="page"><h2>Pipeline health</h2><div class="notice">A dashboard that loads does not mean upstream phases are healthy. Statuses below come from the loaded records; unobserved phases remain unavailable.</div><div id="health-table" class="card"></div><div id="health-note" class="muted"></div><div id="adapter-errors" class="card"></div></section>
<div class="footer">Decision-support interface only. Recommendations are for human review. No autonomous dispatch, live feed, real notification delivery, or Phase 11 persistence/API is provided.</div>
</main>
<script id="dashboard-data" type="application/json">__DATA__</script>
<script>
const D=JSON.parse(document.getElementById('dashboard-data').textContent);const $=id=>document.getElementById(id);const esc=v=>String(v===null||v===undefined||v===''?'Not available':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const txt=v=>Array.isArray(v)?v.join(', '):typeof v==='object'&&v!==null?JSON.stringify(v,null,2):v;const label=v=>esc(v===null||v===undefined||v===''?'Not available':v);const levels={CRITICAL:5,HIGH:4,MEDIUM:3,LOW:2,INFO:1};
const pages=['overview','incidents','alerts','spatial','monitoring','intelligence','health'];$('mode').textContent=D.dataset_label||'PROVIDED DATA';pages.forEach((p,i)=>{const b=document.createElement('button');b.textContent=['Overview','Incidents','Alerts','Spatial','Monitoring','Intelligence','System health'][i];b.onclick=()=>{document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));$(p).classList.add('active');document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active')};if(!i)b.classList.add('active');$('nav').appendChild(b)});
function card(k,v){return `<div class="card"><div class="label">${esc(k)}</div><div class="kpi">${esc(v)}</div></div>`}function renderKpis(){const s=D.summary||{};const items=[['Incidents',s.total_incidents],['Critical incidents',s.critical_incidents],['High priority',s.high_priority_incidents],['Active alerts',s.active_alerts],['Critical alerts',s.critical_alerts],['New events',s.new_monitoring_events],['Updated events',s.updated_events],['Duplicate/suppressed events',s.duplicate_or_suppressed_events],['Unresolved locations',s.unresolved_locations],['Hotspot incidents',s.spatial_hotspots],['Human review',s.requiring_human_review]];$('kpis').innerHTML=items.map(x=>card(x[0],x[1]??'Not available')).join('')}
function chart(el,title,data){const entries=Object.entries(data||{});if(!entries.length){el.innerHTML='<div class="empty">Not available</div>';return}const max=Math.max(1,...entries.map(x=>Number(x[1])||0));el.innerHTML=entries.map(([k,v])=>`<div class="barrow"><span>${esc(k)}</span><div class="bar"><i style="width:${Math.max(0,Math.min(100,(Number(v)||0)*100/max))}%"></i></div><b>${esc(v)}</b></div>`).join('')}
function renderOverview(){renderKpis();chart($('priority-chart'),'Priority',D.summary.priority_distribution);$('score-charts').innerHTML=['severity_level','urgency_level','confidence_level'].map(k=>`<h3>${k.replace('_level','')}</h3><div id="chart-${k}"></div>`).join('');chart($('chart-severity_level'),'Severity',D.summary.severity_distribution);chart($('chart-urgency_level'),'Urgency',D.summary.urgency_distribution);chart($('chart-confidence_level'),'Confidence',D.summary.confidence_distribution);chart($('alert-chart'),'Alert',D.summary.alert_level_distribution);const ranked=[...(D.incidents||[])].filter(x=>x.priority_score!==null&&x.priority_score!==undefined).sort((a,b)=>Number(b.priority_score)-Number(a.priority_score)).slice(0,7);$('ranked').innerHTML=ranked.length?`<table><tr><th>Incident</th><th>Priority</th><th>Score</th><th>Alert</th></tr>${ranked.map(x=>`<tr><td>${label(x.incident_id||x.event_id)}</td><td>${label(x.priority_level)}</td><td>${label(x.priority_score)}</td><td>${label(x.alert_level)}</td></tr>`).join('')}</table>`:'<div class="empty">Priority scores unavailable</div>'}
const fields=[['disaster_type','Disaster'],['priority_level','Priority'],['severity_level','Severity'],['urgency_level','Urgency'],['confidence_level','Confidence'],['alert_level','Alert'],['event_state','Event'],['geocoding_status','Geocoding'],['hotspot','Hotspot'],['spatial_cluster_id','Cluster'],['decision_flag','Decision flag']];function choices(field){return [...new Set((D.incidents||[]).flatMap(x=>field==='decision_flags'?(x.decision_flags||[]):[x[field]]).filter(x=>x!==null&&x!==undefined&&x!==''))].sort()}
function setupFilters(){const root=$('incident-filters');fields.forEach(([key,title])=>{const options=key==='decision_flag'?choices('decision_flags'):choices(key);root.insertAdjacentHTML('beforeend',`<label>${esc(title)}<select data-filter="${key}"><option value="">All</option>${options.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select></label>`)});root.insertAdjacentHTML('beforeend','<label>Sort by<select id="sort-by"><option value="priority_score">Priority score</option><option value="severity_score">Severity score</option><option value="urgency_score">Urgency score</option><option value="confidence_score">Confidence score</option><option value="alert_level">Alert level</option></select></label>');root.onchange=renderIncidents;}
function filtered(){const fs={};document.querySelectorAll('[data-filter]').forEach(x=>{if(x.value)fs[x.dataset.filter]=x.value});return (D.incidents||[]).filter(x=>Object.entries(fs).every(([k,v])=>k==='decision_flag'?(x.decision_flags||[]).includes(v):String(x[k]??'')===v)).sort((a,b)=>{const k=$('sort-by')?.value||'priority_score';if(k==='alert_level')return (levels[b[k]]||0)-(levels[a[k]]||0);const av=a[k],bv=b[k];if(av==null)return bv==null?0:1;if(bv==null)return -1;return Number(bv)-Number(av)})}
function renderIncidents(){const rows=filtered();$('incident-table').innerHTML=rows.length?`<table><tr><th>Incident</th><th>Disaster</th><th>Location</th><th>Priority</th><th>Score</th><th>Severity</th><th>Urgency</th><th>Confidence</th><th>Alert</th><th>Monitoring</th><th>Spatial</th><th>Flags</th></tr>${rows.map((x,i)=>`<tr class="selectable" data-row="${i}"><td>${label(x.incident_id||x.event_id)}</td><td>${label(x.disaster_type)}</td><td>${label(x.normalized_location||x.location_text)}</td><td>${label(x.priority_level)}</td><td>${label(x.priority_score)}</td><td>${label(x.severity_level)}</td><td>${label(x.urgency_level)}</td><td>${label(x.confidence_level)}</td><td><span class="pill level-${esc(x.alert_level)}">${label(x.alert_level)}</span></td><td>${label(x.event_state)}</td><td>${label(x.geocoding_status)}</td><td>${label(x.decision_flags)}</td></tr>`).join('')}</table>`:'<div class="empty">No records match these filters. Records with missing fields remain filterable under All.</div>';document.querySelectorAll('#incident-table [data-row]').forEach(tr=>tr.onclick=()=>showIncident(rows[Number(tr.dataset.row)]))}
function showIncident(x){if(!x)return;const sections=[['A. Incident overview',{incident_id:x.incident_id,event_id:x.event_id,disaster_type:x.disaster_type,canonical_disaster_type:x.canonical_disaster_type,source_disaster_type:x.source_disaster_type,ml_disaster_type:x.ml_disaster_type,type_resolution:x.type_resolution,location:x.location,normalized_location:x.normalized_location,nlp_location_entities:x.nlp_location_entities,source_location:x.source_location,coordinate_source:x.coordinate_source,source:x.source,provenance:x.provenance,source_event_id:x.source_event_id,source_title:x.source_title,source_url:x.source_url,source_event_timestamp:x.source_event_timestamp,source_published_at:x.source_published_at,source_updated_at:x.source_updated_at,source_retrieved_at:x.source_retrieved_at,source_metadata:x.source_metadata,source_coordinates:[x.source_latitude,x.source_longitude]}],['A. Type evidence',{operational_type:x.canonical_disaster_type,source:x.source_authority,source_type:x.source_disaster_type,phase4_nlp_type:x.phase4_disaster_type,ml_prediction:x.ml_disaster_type,ml_confidence:x.ml_confidence==null?null:(Number(x.ml_confidence)*100).toFixed(2)+'%',agreement:x.type_agreement_status==='DISAGREEMENT'?'⚠ MODEL DISAGREEMENT':(x.type_agreement_status||'UNRESOLVED'),model_disagreement:x.model_disagreement,resolution_method:x.resolution_method,resolution_rationale:x.resolution_rationale,warning:x.type_resolution_warning}],['B. Human impact',{casualties:x.casualties,displaced:x.displaced}],['C. Infrastructure',{infrastructure:x.infrastructure}],['D. Rescue / danger',{rescue:x.rescue,decision_flags:x.decision_flags}],['E. Resource requests',{requests:x.requests,resources:x.resources}],['F. Resource estimates',{estimates:x.resource_estimates,heuristic:x.resource_estimates_are_heuristic,disclaimer:'Heuristic estimates are planning aids, not confirmed requirements.'}],['G. Deterministic intelligence',{severity:[x.severity_level,x.severity_score],urgency:[x.urgency_level,x.urgency_score],priority:[x.priority_level,x.priority_score],confidence:[x.confidence_level,x.confidence_score],decision_flags:x.decision_flags}],['H. Spatial intelligence',{location:x.normalized_location||x.location_text,coordinates:x.latitude==null?null:[x.latitude,x.longitude],coordinate_source:x.coordinate_source,geocoding_status:x.geocoding_status,spatial_cluster_id:x.spatial_cluster_id,hotspot:x.hotspot,spatial_priority_score:x.spatial_priority_score}],['I. Grounded generative intelligence',{summary:x.phase7_summary,situation_assessment:x.phase7_situation_assessment,key_evidence:x.phase7_key_evidence,recommendations:x.phase7_recommendations,uncertainties:x.phase7_uncertainties,grounding_warnings:x.grounding_warnings,confidence_note:x.phase7_confidence_note,disclaimer:x.recommendations_disclaimer}],['J. Monitoring',{event_state:x.event_state,processing_status:x.processing_status,event_id:x.event_id,source:x.source,timestamps:{first_seen:x.first_seen,last_seen:x.last_seen,observed_at:x.observed_at,published_at:x.published_at},phase_status:x.phase_status,processing_errors:x.processing_errors}],['K. Alerting',{alert_level:x.alert_level,alert_status:x.alert_status,triggered_rules:x.alert_reasons,escalation:x.alert_escalation,suppression:x.alert_suppression,notification_status:x.notification_status}]];$('incident-detail').innerHTML=`<h3>Incident detail: ${label(x.incident_id||x.event_id)}</h3>${sections.map(([name,obj])=>`<section><b>${esc(name)}</b><pre>${esc(JSON.stringify(obj,null,2))}</pre></section>`).join('')}`}
function setupAlertFilters(){const f=$('alert-filters');[['alert_level','Level'],['alert_status','Status'],['escalated','Escalation'],['suppressed','Suppression'],['notification_status','Notification']].forEach(([k,t])=>{let vals;if(k==='escalated')vals=['true','false'];else if(k==='suppressed')vals=['true','false'];else vals=[...new Set((D.alerts||[]).map(x=>x[k]).filter(v=>v!=null&&v!==''))].sort();f.insertAdjacentHTML('beforeend',`<label>${t}<select data-af="${k}"><option value="">All</option>${vals.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select></label>`)});f.onchange=renderAlerts}
function alertRows(){const fs={};document.querySelectorAll('[data-af]').forEach(x=>{if(x.value)fs[x.dataset.af]=x.value});return [...(D.alerts||[])].filter(x=>Object.entries(fs).every(([k,v])=>{if(k==='escalated')return String(Boolean(x.escalation?.is_escalation))===v;if(k==='suppressed')return String(Boolean(x.suppression?.suppressed))===v;return String(x[k]??'')===v})).sort((a,b)=>(levels[b.alert_level]||0)-(levels[a.alert_level]||0))}
function renderAlerts(){const rows=alertRows();$('alert-table').innerHTML=rows.length?`<table><tr><th>Alert</th><th>Incident</th><th>Level</th><th>Status</th><th>Reason</th><th>Escalation</th><th>Suppression</th><th>Notification</th><th>Location</th><th>Priority</th></tr>${rows.map((x,i)=>`<tr class="selectable" data-alert="${i}"><td>${label(x.alert_id)}</td><td>${label(x.incident_id)}</td><td><b class="level-${esc(x.alert_level)}">${label(x.alert_level)}</b></td><td>${label(x.alert_status)}</td><td>${label(x.explanation)}</td><td>${label(x.escalation?.is_escalation)}</td><td>${label(x.suppression?.reason)}</td><td>${label(x.notification_status)}</td><td>${label(x.location)}</td><td>${label(x.priority_score)}</td></tr>`).join('')}</table>`:'<div class="empty">No alert evaluations in the loaded data.</div>';document.querySelectorAll('#alert-table [data-alert]').forEach(tr=>tr.onclick=()=>{$('alert-detail').innerHTML=`<h3>Alert detail</h3><pre>${esc(JSON.stringify(rows[Number(tr.dataset.alert)].source_record,null,2))}</pre>`})}
function renderMap(){const all=D.spatial_summary?.points||[],w=900,h=410,pad=45,ff=$('map-filters');if(!ff.dataset.ready){const clusters=[...new Set(all.map(x=>x.spatial_cluster_id).filter(Boolean))];ff.innerHTML=`<label>Alert level<select id="map-alert"><option value="">All</option>${['CRITICAL','HIGH','MEDIUM','LOW','INFO'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Cluster<select id="map-cluster"><option value="">All</option>${clusters.map(esc).map(x=>`<option>${x}</option>`).join('')}</select></label><label>Hotspot<select id="map-hotspot"><option value="">All</option><option value="true">Hotspot</option><option value="false">Not hotspot</option></select></label>`;ff.dataset.ready='1';ff.onchange=renderMap}const pts=all.filter(x=>(!$('map-alert').value||x.alert_level===$('map-alert').value)&&(!$('map-cluster').value||x.spatial_cluster_id===$('map-cluster').value)&&(!$('map-hotspot').value||String(Boolean(x.hotspot)==($('map-hotspot').value==='true'))==='true'));if(!pts.length){$('map').innerHTML='<div class="empty">No successfully geocoded valid points match these filters. Unresolved reports are listed below and are not plotted.</div>';return}const lats=pts.map(x=>x.latitude),lons=pts.map(x=>x.longitude),minLat=Math.min(...lats),maxLat=Math.max(...lats),minLon=Math.min(...lons),maxLon=Math.max(...lons),latSpan=maxLat-minLat||1,lonSpan=maxLon-minLon||1;const circles=pts.map((x,i)=>{const cx=pad+(x.longitude-minLon)/lonSpan*(w-pad*2),cy=h-pad-(x.latitude-minLat)/latSpan*(h-pad*2),color=x.alert_level==='CRITICAL'?'#ef6a6a':(x.alert_level==='HIGH'||x.priority_level==='HIGH'?'#f1b85b':'#70a8ff');return `${x.hotspot?`<circle cx="${cx}" cy="${cy}" r="13" fill="none" stroke="#f4d46a" stroke-width="2"/>`:''}<circle class="point" data-point="${i}" cx="${cx}" cy="${cy}" r="7" fill="${color}"><title>${esc(x.incident_id)} | ${esc(x.priority_level)} | ${esc(x.alert_level)} | cluster ${esc(x.spatial_cluster_id)} | ${x.latitude}, ${x.longitude}${x.synthetic_data?' | SYNTHETIC':''}</title></circle>`}).join('');let grid='';for(let i=0;i<5;i++){const y=pad+i*(h-pad*2)/4,x=pad+i*(w-pad*2)/4;grid+=`<line class="mapgrid" x1="${pad}" y1="${y}" x2="${w-pad}" y2="${y}"/><line class="mapgrid" x1="${x}" y1="${pad}" x2="${x}" y2="${h-pad}"/>`} $('map').innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Coordinate plot of Phase 6 success-status points">${grid}${circles}<text x="${w/2}" y="${h-8}" text-anchor="middle" fill="#9aacc3">Longitude (degrees)</text><text transform="translate(15 ${h/2}) rotate(-90)" text-anchor="middle" fill="#9aacc3">Latitude (degrees)</text></svg>`;document.querySelectorAll('#map .point').forEach(c=>c.onclick=()=>{const point=pts[Number(c.dataset.point)],incident=(D.incidents||[]).find(x=>x.incident_id===point.incident_id);$('map-detail').innerHTML=incident?`<h3>Selected incident: ${label(incident.incident_id||incident.event_id)}</h3><p>${label(incident.normalized_location||incident.location_text)} · ${point.latitude}, ${point.longitude} · ${label(incident.geocoding_status)}</p><button class="button" id="map-open-incident">Open incident details</button>`:'<div class="empty">Incident detail unavailable.</div>';const b=$('map-open-incident');if(b)b.onclick=()=>{document.querySelector('#nav button:nth-child(2)').click();showIncident(incident)}})}
function renderSpatial(){renderMap();const s=D.spatial_summary||{};$('spatial-kpis').innerHTML=Object.entries(s).filter(([k,v])=>typeof v==='number').map(([k,v])=>`<div class="health"><b>${esc(k)}</b><span>${esc(v)}</span></div>`).join('');const u=s.unresolved||[];$('unresolved').innerHTML=u.length?`<table><tr><th>Incident</th><th>Location mention</th><th>Geocoding</th></tr>${u.map(x=>`<tr><td>${label(x.incident_id)}</td><td>${label(x.location)}</td><td>${label(x.geocoding_status)}</td></tr>`).join('')}</table>`:'<div class="empty">No unresolved location mentions in the loaded records.</div>'}
function renderMonitoring(){const s=D.monitoring_summary||{};$('monitoring-kpis').innerHTML=Object.entries(s).filter(([k,v])=>typeof v==='number').map(([k,v])=>card(k,v)).join('');const ev=D.monitoring_events||[];$('monitoring-table').innerHTML=ev.length?`<table><tr><th>Event</th><th>Source</th><th>Event state</th><th>Processing</th><th>Incident</th><th>Phases</th><th>Errors</th></tr>${ev.map(x=>`<tr><td>${label(x.event_id)}</td><td>${label(x.source)}</td><td>${label(x.event_state)}</td><td>${label(x.processing_status)}</td><td>${label(x.intelligence?.phase5?.incident_id)}</td><td>${label(x.phase_status)}</td><td>${label(x.processing_errors?.map(e=>e.phase+': '+e.error_type))}</td></tr>`).join('')}</table>`:'<div class="empty">Monitoring events unavailable.</div>';const statuses={};ev.forEach(x=>Object.entries(x.phase_status||{}).forEach(([k,v])=>(statuses[k]??={})[v]=(statuses[k][v]||0)+1));$('phase-statuses').innerHTML=Object.keys(statuses).length?Object.entries(statuses).map(([p,vals])=>`<div class="health"><b>${esc(p)}</b><span>${esc(Object.keys(vals).join(', '))}</span><span>${esc(JSON.stringify(vals))}</span></div>`).join(''):'<div class="empty">Phase status not reported in these events.</div>'}
function renderIntelligence(){const select=$('intelligence-select'),recs=D.incidents||[];select.innerHTML=recs.map((x,i)=>`<option value="${i}">${esc(x.incident_id||x.event_id||'Unavailable')}</option>`).join('');function show(){const x=recs[Number(select.value)]||{};$('intelligence-detail').innerHTML=`<h3>${label(x.incident_id||x.event_id)}</h3><section><b>Grounded generative intelligence</b><pre>${esc(x.phase7_summary)}</pre><pre>${esc(x.phase7_situation_assessment)}</pre></section><section><b>Key evidence</b><pre>${esc(JSON.stringify(x.phase7_key_evidence,null,2))}</pre></section><section><b>Recommendations (human review only)</b><pre>${esc(JSON.stringify(x.phase7_recommendations,null,2))}</pre></section><section><b>Uncertainties</b><pre>${esc(JSON.stringify(x.phase7_uncertainties,null,2))}</pre></section><section><b>Grounding warnings</b><pre>${esc(JSON.stringify(x.grounding_warnings,null,2))}</pre></section><p class="muted">${esc(D.intelligence_summary?.disclaimer)}</p>`}select.onchange=show;if(recs.length)show();else $('intelligence-detail').innerHTML='<div class="empty">Grounded generative outputs unavailable.</div>'}
function renderHealth(){const h=D.system_health||{};$('health-table').innerHTML=Object.entries(h).filter(([k,v])=>typeof v==='object').map(([k,v])=>`<div class="health"><b>${esc(k.toUpperCase())}</b><span class="${v.status==='successful'?'good':v.status==='degraded'?'warn':v.status==='failed'?'bad':''}">${esc(v.status)}</span><span>${esc(JSON.stringify(v.observed_statuses||{}))} <span class="muted">(${esc(v.observations)} records)</span></span></div>`).join('');$('health-note').textContent=h.environment_note||'';const e=D.adapter_errors||[];$('adapter-errors').innerHTML=`<h3>Dashboard adapter errors</h3>${e.length?`<pre>${esc(JSON.stringify(e,null,2))}</pre>`:'<span class="good">No adapter errors.</span>'}`}
setupFilters();setupAlertFilters();renderOverview();renderIncidents();renderAlerts();renderSpatial();renderMonitoring();renderIntelligence();renderHealth();
</script></body></html>'''


def render_dashboard(data):
    """Render one self-contained HTML page; all user/source data is JSON-escaped."""
    payload = json.dumps(data, ensure_ascii=False, separators=(",", ":"), allow_nan=False)
    payload = payload.replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    return _HTML.replace("__DATA__", payload)
